import assert from "node:assert/strict";
import { test } from "node:test";
import { decide } from "../screens/access.ts";
import { schema } from "../app/books/[bookId]/edit/page.schema.ts";

test("book-edit is refused to someone signed in without books.write", () => {
  assert.equal(decide(schema.permission, { signedIn: true, permissions: [] }), "refused");
});

test("book-edit sends someone signed out to sign in", () => {
  assert.equal(decide(schema.permission, { signedIn: false, permissions: [] }), "sign-in");
});

test("book-edit opens to someone who holds books.write", () => {
  assert.equal(decide(schema.permission, { signedIn: true, permissions: ["books.write"] }), "allowed");
});
